App.Http.Stations=function(){function t(t){const s=App.Utils.Url.siteUrl("stations/store");return $.post(s,{csrf_token:vars("csrf_token"),station:t})}function s(t){const s=App.Utils.Url.siteUrl("stations/update");return $.post(s,{csrf_token:vars("csrf_token"),station:t})}return{save:function(n){return n.id?s(n):t(n)},store:t,update:s,destroy:function(t){const s=App.Utils.Url.siteUrl("stations/destroy");return $.post(s,{csrf_token:vars("csrf_token"),station_id:t})},search:function(t,s=null,n=null){const r=App.Utils.Url.siteUrl("stations/search");return $.post(r,{csrf_token:vars("csrf_token"),keyword:t,limit:s,offset:n})},find:function(t){const s=App.Utils.Url.siteUrl("stations/find");return $.post(s,{csrf_token:vars("csrf_token"),station_id:t})}}}();